-- Fail when the optional REF Batch pack is incomplete.
DECLARE
  V_COUNT NUMBER;
BEGIN
  SELECT COUNT(*) INTO V_COUNT FROM USER_TABLES WHERE TABLE_NAME IN ('CPF_REF_BAT_JOB_EXECUTION','CPF_REF_BAT_CHECKPOINT','CPF_REF_BAT_TARGET_RESULT');
  IF V_COUNT <> 3 THEN RAISE_APPLICATION_ERROR(-20994, 'CPF REF Batch table count mismatch'); END IF;
  SELECT COUNT(*) INTO V_COUNT FROM USER_INDEXES WHERE INDEX_NAME IN ('IX_REF_BAT_JOB_STATE','IX_REF_BAT_JOB_BIZ','IX_REF_BAT_CP_STATE','IX_REF_BAT_TARGET_STATE');
  IF V_COUNT <> 4 THEN RAISE_APPLICATION_ERROR(-20993, 'CPF REF Batch index count mismatch'); END IF;
END;
/
